import{g as a,ad as n,r as p,A as e}from"./chunks/framework.Bv4C6ofj.js";const h=JSON.parse('{"title":"Utilities","description":"","frontmatter":{},"headers":[],"relativePath":"docs/other/utilities.md","filePath":"docs/other/utilities.md","lastUpdated":1786054579000}'),c={name:"docs/other/utilities.md"};function l(t,s,o,i,r,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to “Utilities”">​</a></h1><p>Some common utilities that are useful in building frontend apps.</p><h2 id="call" tabindex="-1">call <a class="header-anchor" href="#call" aria-label="Permalink to “call”">​</a></h2><p>Calls a whitelisted method on the server and resolves to its <code>message</code>. The method is a dotted path; an argument object becomes the JSON request body.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">call</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">let</span><span class="s_2a1oer"> count</span><span class="s_2ekfrt"> =</span><span class="s_29n2kq"> await</span><span class="s_indoxt"> call</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">frappe.client.get_count</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span></code></pre></div><p>Pass a path starting with <code>/</code> to hit it directly instead of <code>/api/method/…</code>.</p><p>A third argument takes <code>headers</code> (merged over the defaults, winning over anything from <a href="#configuration"><code>setConfig(&#39;requestHeaders&#39;)</code></a>) and <code>onError</code>, which receives <code>{ response, status, error }</code> for a failed HTTP response. The promise rejects either way — <code>onError</code> is for reporting, not for recovery.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_29n2kq">await</span><span class="s_indoxt"> call</span><span class="s_13ahmt">(</span></span>
<span class="line"><span class="s_w1p9wo">  &#39;</span><span class="s_2575z4">my_app.api.save</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  {</span><span class="s_22m8k2"> name</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  {</span><span class="s_indoxt"> onError</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> error</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_22m8k2"> toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">error</span><span class="s_13ahmt">(</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">messages</span><span class="s_13ahmt">[</span><span class="s_40mev6">0</span><span class="s_13ahmt">])</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">)</span></span></code></pre></div><p>The rejection is a <code>FrappeRequestError</code>: an <code>Error</code> with <code>exc_type</code>, <code>exc</code>, <code>status</code>, <code>response</code>, and <code>messages</code> (the server&#39;s <code>_server_messages</code>, already parsed).</p><h2 id="frapperequest" tabindex="-1">frappeRequest <a class="header-anchor" href="#frapperequest" aria-label="Permalink to “frappeRequest”">​</a></h2><p>The transport <code>call</code> is built on, for requests <code>call</code> doesn&#39;t shape — a <code>GET</code>, a non-method URL, a request you need to abort.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">frappeRequest</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">let</span><span class="s_2a1oer"> doc</span><span class="s_2ekfrt"> =</span><span class="s_29n2kq"> await</span><span class="s_indoxt"> frappeRequest</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/resource/ToDo/TODO-0001</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  method</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">GET</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span></code></pre></div><p>Options: <code>url</code> (required), <code>method</code> (defaults to <code>POST</code>), <code>params</code> (query string on <code>GET</code>, JSON body otherwise), <code>headers</code>, <code>signal</code>, <code>credentials</code>, <code>responseType</code> (<code>&#39;json&#39;</code> or <code>&#39;response&#39;</code>), and the <code>onError</code> / <code>onServerMessages</code> callbacks. It sets the <code>Accept</code>, <code>Content-Type</code>, <code>X-Frappe-Site-Name</code> and CSRF headers, unwraps <code>message</code> from the response, and throws a <code>FrappeRequestError</code> on failure.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h3><p>Both <code>call</code> and <code>frappeRequest</code> read these through <code>setConfig</code>:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">setConfig</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// point requests at a remote site during local development</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">requestBaseUrl</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">https://my-site.frappe.cloud</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_1th9sy">// merged into every request; pass a function for values that change</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">requestHeaders</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span><span class="s_r4oegk"> Authorization</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> \`</span><span class="s_2575z4">token </span><span class="s_20l85h">\${</span><span class="s_22m8k2">key</span><span class="s_20l85h">}</span><span class="s_2575z4">:</span><span class="s_20l85h">\${</span><span class="s_22m8k2">secret</span><span class="s_20l85h">}</span><span class="s_w1p9wo">\`</span><span class="s_13ahmt"> }))</span></span>
<span class="line"><span class="s_1th9sy">// called with the server&#39;s _server_messages on a successful response</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">serverMessagesHandler</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> (</span><span class="s_fsg3al">messages</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_22m8k2"> messages</span><span class="s_1jjt6x">.</span><span class="s_indoxt">forEach</span><span class="s_13ahmt">(</span><span class="s_22m8k2">toast</span><span class="s_13ahmt">))</span></span></code></pre></div><p>Setting <code>requestBaseUrl</code> makes relative requests cross-origin and defaults them to <code>credentials: &#39;include&#39;</code>, so the server has to send <code>Access-Control-Allow-Credentials: true</code> and a non-wildcard origin. If you authenticate with a token header instead, pass <code>credentials: &#39;omit&#39;</code> per request.</p><h2 id="frappeui-plugin" tabindex="-1">FrappeUI plugin <a class="header-anchor" href="#frappeui-plugin" aria-label="Permalink to “FrappeUI plugin”">​</a></h2><p>An optional Vue plugin with one option. It installs the v1 resources Options API mixin — the <code>resources: { … }</code> component option, <code>this.$resources</code>, and the <code>$getResource</code> / <code>$getDoc</code> / <code>$getListResource</code> / <code>$refetchResource</code> helpers.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">FrappeUI</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">FrappeUI</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> resources</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span></span></code></pre></div><p>You do not need it otherwise. Components, the imperative <code>dialog</code> and <code>toast</code> APIs, and every Composition API data helper work without installing anything — wrap your app in <a href="./../getting-started"><code>FrappeUIProvider</code></a> instead. Passing an option the plugin doesn&#39;t accept logs a warning in development.</p><h2 id="debounce" tabindex="-1">debounce <a class="header-anchor" href="#debounce" aria-label="Permalink to “debounce”">​</a></h2><p>Creates a function that will run only once in the specified number of wait time (milliseconds). In the following example, if you run <code>debouncedInput</code> function every time the user presses a key, it will run only once in every <code>500ms</code>.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">debounce</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> onInput</span><span class="s_13ahmt">(</span><span class="s_fsg3al">e</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_1th9sy">  // do something with input event</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">let</span><span class="s_2a1oer"> debouncedInput</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> debounce</span><span class="s_13ahmt">(</span><span class="s_22m8k2">onInput</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 500</span><span class="s_13ahmt">)</span></span></code></pre></div><h2 id="filetobase64" tabindex="-1">fileToBase64 <a class="header-anchor" href="#filetobase64" aria-label="Permalink to “fileToBase64”">​</a></h2><p>This function will return the base64 string of a <a href="https://developer.mozilla.org/en-US/docs/Web/API/File_API" target="_blank" rel="noreferrer">File object</a>.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">fileToBase64</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">let</span><span class="s_2a1oer"> base64</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> fileToBase64</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_13ahmt">)</span><span class="s_1th9sy"> // file must be an instance of File</span></span></code></pre></div><h2 id="pagemeta" tabindex="-1">pageMeta <a class="header-anchor" href="#pagemeta" aria-label="Permalink to “pageMeta”">​</a></h2><p>This is a plugin that can be used to update the <code>document.title</code> reactively as the page changes.</p><p>Register the plugin in your <code>main.js</code> file.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">pageMetaPlugin</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_1th9sy">// ...</span></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">pageMetaPlugin</span><span class="s_13ahmt">)</span></span></code></pre></div><p>Now, in your page component, declare the <code>pageMeta</code> function. It must return an object with <code>title</code> and (<code>icon</code> or <code>emoji</code>) properties. The <code>pageMeta</code> function behaves like a computed property, if there are reactive dependences that change, <code>document.title</code> will also change accordingly.</p><p><strong>Page.vue</strong></p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">...</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_fjrnv8">    ...</span></span>
<span class="line"><span class="s_indoxt">    pageMeta</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_6am9cx">        return </span><span class="s_13ahmt">{</span></span>
<span class="line"><span class="s_g1fsda">            title</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Page Title</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">            icon</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">&lt;link to .png, .ico file&gt;</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_g1fsda">            emoji</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">🌈</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_13ahmt">        }</span></span>
<span class="line"><span class="s_13ahmt">    }</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div>`,34)])])}const u=a(c,[["render",l]]);export{h as __pageData,u as default};
